INSERT INTO `paginas` VALUES
(1,'Sobre Nós','<p style=\"text-align: justify;\"><span style=\"font-size: small;\"><span style=\"color: #888888;\">H&aacute; mais de dez anos representando e trabalhando como produtor art&iacute;stico da musica sertaneja, Magal j&aacute; trabalhou e representou grandes nomes que hoje &eacute; sucesso pelo Brasil a fora, exemplo o locutor de rodeio Junior Cuiabano, que representou Mato Grosso em Barretos-SP.<br /><br /></span></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"font-size: small;\"><span style=\"color: #888888;\">Como empres&aacute;rio e produtor art&iacute;stico fez parte da forma&ccedil;&atilde;o da dupla Jo&atilde;o Carreiro &amp; Capataz, que hoje &eacute; sucesso a n&iacute;vel nacional. J&aacute; em estilo diferente como empres&aacute;rio, Magal fez um grande trabalho com o Grupo Forr&oacute; Transito Livre. E n&atilde;o para por ai, foram cinco anos como produtor art&iacute;stico e representando a dupla Alecir e Alessandro que hoje &eacute; sucesso em v&aacute;rios estados.</span></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"font-size: small;\"><span style=\"color: #888888;\"><br /></span></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"font-size: small;\"><span style=\"color: #888888;\">Vendo as dificuldades e necessidades por partes dos artistas em fazer um trabalho de divulga&ccedil;&atilde;o dentro do estado de Mato Grosso, e acreditando que Cuiab&aacute;, e Mato Grosso tem artistas preparado e qualificados, com estruturas e equipe de profissionais prontos para representar o estado, sabendo tamb&eacute;m que temos casa de shows com uma super estrutura para receber artistas a n&iacute;vel nacional, est&uacute;dio de grava&ccedil;&atilde;o de CD e DVD com o mais alto n&iacute;vel de qualidade do Brasil. Acreditando e sabendo de tudo isso e muito mais Magal lan&ccedil;a o seu novo desafio (Magal divulga&ccedil;&otilde;es art&iacute;sticas).</span></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"font-size: small;\"><span style=\"color: #888888;\"><br /></span></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"font-size: small;\"><span style=\"color: #888888;\">Com objetivo de prestar um servi&ccedil;o de divulga&ccedil;&atilde;o direcionado somente no estado de Mato Grosso, divulgando os artistas que est&atilde;o preparados para o caminho do sucesso, fazer um trabalho de divulga&ccedil;&atilde;o dentro das cidades p&oacute;los do estado, levando o seu trabalho de CD e DVD, brindes em todas as r&aacute;dios de cada munic&iacute;pios, visitar prefeituras, sindicato rurais, faculdades, casa de shows promoter, enfim levar o material onde o artista tem que ser visto ou ouvido. Fazer um trabalho com transpar&ecirc;ncia e qualidade dando toda tranq&uuml;ilidade para o artista. Acompanhar a execu&ccedil;&atilde;o da musica do artista nas r&aacute;dios prestar conta e passar um relat&oacute;rio do servi&ccedil;o prestado. Fazer promo&ccedil;&otilde;es na radio l&iacute;der de audi&ecirc;ncias de cada munic&iacute;pio em busca de uma parceria e shows.</span></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"font-size: small;\"><span style=\"color: #888888;\"><br /></span></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"font-size: small;\"><span style=\"color: #888888;\">Para inicio iremos come&ccedil;ar os trabalhos, no Maximo com tr&ecirc;s artistas em estilos diferentes. As viajem ser&atilde;o feitas pelo pr&oacute;prio Magal Ser&atilde;o visitadas todas as cidades p&oacute;los do Estado de Mato Grosso Com o objetivo principal de fortalecer ou fazer o nome do artista, dando tranq&uuml;ilidade ao contratante de cada munic&iacute;pio que ir&aacute; contratar o show. Acreditando nesse projeto e com o desafio de buscar novas experi&ecirc;ncias e aprendizados. Magal divulga&ccedil;&otilde;es art&iacute;sticas convida voc&ecirc;s venha divulgar seu artista no Estado de Mato Grosso.</span></span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: small;\"><span style=\"color: #000000;\"><strong>Nosso Objetivo</strong></span></span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: small;\"><span style=\"color: #888888;\">Fazer um trabalho com transpar&ecirc;ncia e qualidade dando toda tranquilidade ao artista, fortalecendo seu nome nos principais munic&iacute;pios do estado de Mato Grosso. Fazer o artista ser visto, ouvido e suas m&uacute;sicas serem tocadas nas r&aacute;dios. Assim fomentando shows para que o artista tenha retorno de seus investimentos.</span></span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: small;\"><span style=\"color: #888888;\">Acreditando nesse projeto e com o desafio de buscar novas experi&ecirc;ncias e aprendizados. <br />Magal divulga&ccedil;&otilde;es art&iacute;sticas convida voc&ecirc;s. Venha divulgar seu artista no estado de Mato Grosso.<br /></span></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"font-size: small;\"><span style=\"color: #888888;\"><br /></span></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"font-size: small;\"><span style=\"color: #888888;\">Atenciosamente Magal</span></span></p>','2024-07-11 00:16:11','sobre-nos'),
(2,'Serviços','<p><span style=\"color: #000000;\"><strong><span style=\"font-size: medium;\">Veja como &eacute; realizado o trabalho de divulga&ccedil;&otilde;es de nossos artistas no estado de Mato Grosso.<br /></span></strong></span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"><br /></span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"><span style=\"font-size: small;\"><strong>1. Cidades Polos </strong><br />Ser&atilde;o visitadas R&aacute;dios, prefeituras, sindicatos rurais, casa de shows, faculdades e promotores de shows e eventos em todas as cidades p&oacute;los do estado de mato grosso levando o material de divulga&ccedil;&atilde;o do artista, CD, DVD e brindes para promo&ccedil;&otilde;es.</span></span></p>\r\n<p><span style=\"color: #000000;\"><span style=\"font-size: small;\"><img style=\"float: left;\" title=\"Cidades polos\" src=\"http://www.magalproducoes.com.br/uploads/images/novo_roteiro.jpg\" alt=\"Cidades polos\" /></span></span></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000;\"><span style=\"font-size: small;\"><span><strong>2. R&aacute;dios</strong></span><br />Levar para as r&aacute;dios l&iacute;deres de audi&ecirc;ncia, o material de divulga&ccedil;&atilde;o do artista buscando uma parceria e criando mais aproxima&ccedil;&atilde;o entre ambos, fortalecendo NOME/MARCA do artista. Tudo ser&aacute; acompanhado atrav&eacute;s de relat&oacute;rio completo com telefones e nome de todas as r&aacute;dios visitadas.</span></span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"><span style=\"font-size: small;\"><img title=\"R&aacute;dios\" src=\"http://www.magalproducoes.com.br/uploads/images/radio.jpg\" alt=\"R&aacute;dios\" /><br /></span></span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"><span style=\"font-size: small;\"><br />&nbsp; </span></span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"><span style=\"font-size: small;\"><strong>3. Sindicato Rural </strong><br />Mostrar o trabalho do artista que esta sendo realizado dentro dos munic&iacute;pios e regi&atilde;o, visando fomentar shows nas feiras, exposi&ccedil;&otilde;es e agropecu&aacute;ria, rodeio etc.</span></span></p>\r\n<p><span style=\"color: #000000;\"><span style=\"font-size: small;\"><img title=\"Sindicato rural\" src=\"http://www.magalproducoes.com.br/uploads/images/agro.jpg\" alt=\"Sindicato rural\" /><br /></span></span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"><span style=\"font-size: small;\"><br /></span></span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"><br /></span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"><span style=\"font-size: small;\"><strong>4. Prefeituras </strong><br />Apresentar os investimentos realizados pelo artista dentro do munic&iacute;pio, mostrar que suas musicas est&atilde;o sendo executadas nas r&aacute;dios, e que tem publico e esta preparado para as festas comemorativas da cidade.</span></span></p>\r\n<p><span style=\"color: #000000;\"><span style=\"font-size: small;\"><img title=\"Prefeituras\" src=\"http://www.magalproducoes.com.br/uploads/images/prefeitura.jpg\" alt=\"Prefeituras\" /><br /></span></span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"><strong><br /></strong></span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"><span style=\"font-size: small;\"><strong>5. Faculdades </strong><br />Levar o material de divulga&ccedil;&atilde;o, CDs e DVDs aos universit&aacute;rios que s&atilde;o formadores de opini&otilde;es, agregando valores ao nome do artista. Tendo em vista que os movimentos universit&aacute;rios s&atilde;o grandes realizadores de eventos. </span></span></p>\r\n<p><span style=\"color: #000000;\"><span style=\"font-size: small;\"><img title=\"Faculdades\" src=\"http://www.magalproducoes.com.br/uploads/images/faculdade.jpg\" alt=\"Faculdades\" /><br /></span></span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"><br /></span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"><span style=\"font-size: small;\"><strong>6. Casas de Shows </strong><br />Buscar parceria, melhor organiza&ccedil;&atilde;o e estrutura, para os artistas fazerem bons shows, oferecendo qualidade, conforto e tranquilidade ao seu p&uacute;blico</span>.</span></p>\r\n<p><span style=\"color: #000000;\"><img title=\"casa de show\" src=\"http://www.magalproducoes.com.br/uploads/images/casa_show.jpg\" alt=\"Casa de Show\" width=\"891\" height=\"110\" /><br /></span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"><br /></span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"><br /></span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"> </span></p>\r\n<p><span style=\"color: #000000;\"><span style=\"font-size: small;\"><strong>7. Promotores de Eventos </strong><br />Visitar os promotores visando transpar&ecirc;ncia referencia no munic&iacute;pio e regi&atilde;o, experi&ecirc;ncia em parceria para que ambos tenham tranquilidade e um evento com resultado positivo e um grande sucesso.</span></span></p>\r\n<p><span style=\"color: #000000;\"><span style=\"font-size: small;\"><img title=\"promotor de eventos\" src=\"http://www.magalproducoes.com.br/uploads/images/promotor-eventos.jpg\" alt=\"promotor de eventos\" width=\"891\" height=\"110\" /><br /></span></span></p>','2024-07-11 00:16:31','servicos');
